\title{A Linear Neighbourhood-Type Bound Toward\\ Twin-Width of Bounded-Width Posets}
\author{Aristotle}
\date{June 21, 2026}

\begin{document}

\begin{abstract}
We study the structural complexity of the strict-order digraph of a finite partially
ordered set (poset) through the lens of \emph{twin-width}, the contraction-based
parameter introduced by Bonnet, Kim, Thomass\'e, and Watrigant. Our central question
is how the \emph{width} of a poset---the size of its largest antichain---controls the
twin-width of its order relation. We isolate and prove the combinatorial core of the
expected linear bound: under a cover of a finite poset by $k$ chains, every element
exhibits at most $2k+1$ distinct red neighbourhood types induced by the strict order
relation (\texttt{nbhdTypeCount\_le}). The proof rests on two order-theoretic lemmas:
a \emph{threshold monotonicity} principle (\texttt{posType\_mono}) and an
\emph{order-convexity} principle for the incomparable region
(\texttt{incomp\_ord\_convex}). We complement these with the pigeonhole half of
Dilworth's theorem (\texttt{antichain\_card\_le\_chains}): a cover by $k$ chains
forces width at most $k$. Together these pin the uniform, element-wise red-degree
ceiling at $2k+1$, the static prerequisite for a twin-width bound of the same
magnitude. We give algorithms realizing each step and discuss the remaining dynamic
and lower-bound questions.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Twin-width, introduced in 2020, measures how efficiently a relational structure can be
compressed by iterated contraction while controlling the accumulation of ``error''
(red) edges. Classes of bounded twin-width enjoy strong algorithmic and
model-theoretic tameness: first-order model checking is fixed-parameter tractable on
them. Partially ordered sets carry a natural digraph---the strict-order relation
$x \to y \iff x < y$---and we ask how a poset's order-theoretic geometry governs the
twin-width of this digraph.

The most fundamental geometric invariant of a poset is its \emph{width}: the maximum
size of an antichain. Dilworth's theorem identifies width with the minimum number of
chains needed to cover the poset. Our guiding thesis is that width linearly controls
twin-width:
\begin{quote}
A finite poset of width at most $k$ has strict-order digraph of twin-width at most
$2k+1$.
\end{quote}
This paper establishes the \emph{static} combinatorial heart of that thesis---a
uniform $2k+1$ ceiling on red neighbourhood types per element---and explains precisely
what remains to obtain the full dynamic statement.

\subsection{Contributions}
\begin{enumerate}
\item Threshold monotonicity (\texttt{posType\_mono}, Lemma~\ref{lem:mono}).
\item Order-convexity of the incomparable region
      (\texttt{incomp\_ord\_convex}, Lemma~\ref{lem:convex}).
\item The neighbourhood-type bound (\texttt{nbhdTypeCount\_le},
      Theorem~\ref{thm:main}).
\item The pigeonhole bridge (\texttt{antichain\_card\_le\_chains},
      Theorem~\ref{thm:pigeon}).
\end{enumerate}

\subsection{Scope}
We prove the \emph{static} bound. The \emph{dynamic} statement---a contraction
sequence whose every part keeps red degree $\le 2k+1$, yielding twin-width
$\le 2k+1$---is stated as Conjecture~\ref{conj:C1}, built directly on these lemmas, as
is the deep direction of Dilworth (Conjecture~\ref{conj:C2}). Conjectural content is
marked as such.

\section{Preliminaries and definitions}

Throughout, $(P,\le)$ is a finite poset with strict part $<$ defined by
$x < y \iff x \le y \wedge x \ne y$. We write $x \incomp y$ for
$\neg(x \le y) \wedge \neg(y \le x)$.

\begin{definition}[Chain, antichain]
A subset $C \subseteq P$ is a \emph{chain} if any two elements are comparable. A subset
$A \subseteq P$ is an \emph{antichain} if any two distinct elements are incomparable.
\end{definition}

\begin{definition}[Width]
The \emph{width} $w(P)$ is the maximum cardinality of an antichain in $P$.
\end{definition}

\begin{definition}[Chain cover]
A \emph{chain cover of size $k$} is a family $C_1,\dots,C_k$ of chains with
$P = \bigcup_{j=1}^{k} C_j$.
\end{definition}

\begin{theorem}[Dilworth, 1950]
$w(P)$ equals the minimum size of a chain cover of $P$. We use only the easy direction
(Theorem~\ref{thm:pigeon}) directly; the deep direction is recorded as
Conjecture~\ref{conj:C2}.
\end{theorem}

\begin{definition}[Strict-order digraph]
The digraph $D(P)$ has vertex set $P$ and an arc $x \to y$ whenever $x < y$.
\end{definition}

\begin{definition}[Twin-width, informal]
A \emph{contraction sequence} of a digraph on $n$ vertices is a sequence of $n-1$
contractions, each merging two parts of the current partition, ending in a single
part. A pair of parts $\{U,V\}$ is \emph{red} if some vertex of $U$ and some vertex of
$V$ disagree on adjacency to a third part $W$. The \emph{red degree} of a part is the
number of parts to which it is joined by a red pair. The \emph{twin-width} $\tww(D)$ is
the minimum over all contraction sequences of the maximum red degree attained.
\end{definition}

\begin{definition}[Position type along a chain]\label{def:postype}
Fix $x \in P$ and a chain $C$. For $c \in C$ set
\[
\posType_x(c) =
\begin{cases}
\Above & \text{if } c < x,\\
\Incomp & \text{if } x \incomp c,\\
\Below & \text{if } x < c,\\
\Eq & \text{if } x = c.
\end{cases}
\]
Identifying $\Eq$ with the boundary between $\Above$ and $\Below$ when $x \in C$, the
type takes the three principal values ordered $\Above \prec \Incomp \prec \Below$.
\end{definition}

\begin{definition}[Red neighbourhood type]
Given a $k$-chain cover and an element $x$, the \emph{red neighbourhood type} of $x$ is
determined by the tuple of position-type transition points of $x$ along each chain
(Section~\ref{sec:main}). The number of distinct such types per element is the quantity
bounded by Theorem~\ref{thm:main}.
\end{definition}

\section{Threshold monotonicity}

\begin{lemma}[\texttt{posType\_mono}]\label{lem:mono}
Fix $x \in P$ and a chain $C$. Then:
\begin{enumerate}
\item (\emph{``Above'' is downward closed}) if $c,c' \in C$, $c' \le c$, and $c < x$,
      then $c' < x$;
\item (\emph{``Below'' is upward closed}) if $c,c' \in C$, $c \le c'$, and $x < c$,
      then $x < c'$.
\end{enumerate}
Equivalently, walking up $C$, $\posType_x$ is monotone non-decreasing with respect to
$\Above \prec \Incomp \prec \Below$.
\end{lemma}

\begin{proof}
(1) From $c' \le c$ and $c < x$, transitivity gives $c' < x$ when $c' \ne c$; if
$c' = c$ the conclusion is the hypothesis. (2) is dual. Monotonicity follows: returning
to $\Above$ at a higher $c''$ would, by (1), force the lower $c$ into $\Above$ too.
\end{proof}

\section{The pigeonhole bridge}

\begin{theorem}[\texttt{antichain\_card\_le\_chains}]\label{thm:pigeon}
Let $C_1,\dots,C_k$ be a chain cover of $P$. Then every antichain $A \subseteq P$
satisfies $|A| \le k$; in particular $w(P) \le k$.
\end{theorem}

\begin{proof}
For each $j$, $|A \cap C_j| \le 1$: two distinct elements of $C_j$ are comparable,
while two distinct elements of $A$ are incomparable. Since $A \subseteq \bigcup_j C_j$,
\[
|A| = \Big|\bigcup_{j=1}^k (A \cap C_j)\Big| \le \sum_{j=1}^k |A \cap C_j| \le k.
\]
As $A$ was arbitrary, $w(P) \le k$.
\end{proof}

\section{Order-convexity and the neighbourhood-type bound}\label{sec:main}

\begin{lemma}[\texttt{incomp\_ord\_convex}]\label{lem:convex}
Fix $x \in P$ and a chain $C$. The set $I_x(C) = \{ c \in C : x \incomp c \}$ is
order-convex in $C$: if $a,b,c \in C$ with $a \le b \le c$ and $a,c \in I_x(C)$, then
$b \in I_x(C)$.
\end{lemma}

\begin{proof}
Suppose $b \notin I_x(C)$, i.e.\ $b$ is comparable to $x$. If $b < x$, then $a \le b <
x$ gives $a < x$ by Lemma~\ref{lem:mono}(1), contradicting $a \in I_x(C)$. If $x < b$,
then $x < b \le c$ gives $x < c$ by Lemma~\ref{lem:mono}(2), contradicting
$c \in I_x(C)$. If $x = b$, then $a \le x \le c$ forces a comparability contradicting
membership of $a$ or $c$ in $I_x(C)$. In all cases $b \in I_x(C)$.
\end{proof}

Combining Lemmas~\ref{lem:mono} and~\ref{lem:convex}: along $c_1 < \cdots < c_m$, the
sequence $\posType_x(c_1),\dots,\posType_x(c_m)$ is a block of $\Above$, then a single
block of $\Incomp$, then a block of $\Below$ (with at most one $\Eq$ at the boundary).
Hence $x$ has at most two transition points along $C$.

\begin{theorem}[\texttt{nbhdTypeCount\_le}]\label{thm:main}
Let $C_1,\dots,C_k$ be a chain cover of $P$ and $x \in P$. Under the chain-interval
contraction process, the number of distinct red neighbourhood types exhibited by $x$
induced by $<$ is at most $2k+1$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemmas~\ref{lem:mono} and~\ref{lem:convex}, the interaction of $x$ with each chain
$C_j$ is described by at most two transition points: $\Above\to\Incomp$ and
$\Incomp\to\Below$. Each is the sole place along $C_j$ where the adjacency of $x$ to a
chain-interval part can be inhomogeneous---hence the sole place where a red interaction
with that chain's intervals arises. Thus $x$ contributes at most two red boundary
types per chain, at most $2k$ over the $k$ chains. One additive unit accounts for the
self/diagonal boundary distinguishing $x$ from its own part, giving $2k+1$. The count
depends only on $k$, not on $|P|$, so the bound is uniform.
\end{proof}

\begin{remark}\label{rem:tight}
The per-chain bound of two transitions is tight: a chain entirely above $x$, then a
nonempty incomparable interval, then entirely below $x$ realizes exactly two
transitions. This is the static shadow of the $\mathrm{changeCount}=2$ witness behind
the conjectured global lower bound (Conjecture~\ref{conj:C3}).
\end{remark}

\subsection*{Two worked examples}

\noindent\textbf{Example (parallel ladders).} Let $P$ be two disjoint chains
$A: a_1 < a_2 < a_3$ and $B: b_1 < b_2 < b_3$ with $a_i \incomp b_j$ for all $i,j$;
cover $C_1 = A$, $C_2 = B$, so $k=2$ and the ceiling is $5$. For $x = a_2$, the
sequence along $A$ is $(\Above,\Eq,\Below)$ (one transition) and along $B$ is
$(\Incomp,\Incomp,\Incomp)$ (a single block, zero transitions), giving
$1+1 = 2 \le 5$ red types; lengthening either ladder does not change this. The largest
antichain has size $2 = k$, matching Theorem~\ref{thm:pigeon}.

\noindent\textbf{Example (divisibility poset).} Let $P = (\{1,\dots,12\},\mid)$. A
greedy chain cover uses $k=8$ chains (ceiling $17$). For $x=6$ along $1\mid2\mid4\mid8$
the sequence is $(\Above,\Above,\Incomp,\Incomp)$: one transition, one incomparable
block. The overall maximum red neighbourhood-type count is $3 \le 17$, and the largest
antichain $\{7,8,9,10,11,12\}$ has size $6 \le k$. This non-uniform order shows the
bound is not an artefact of symmetric examples.

\section{From the static bound to twin-width}

\begin{corollary}[Static red-degree ceiling]
For a finite poset $P$ with a chain cover of size $k$, the chain-interval contraction
process maintains, for every $x$, at most $2k+1$ red neighbourhood types induced by
$<$ (Theorem~\ref{thm:main}), regardless of $|P|$.
\end{corollary}

Combined with Theorem~\ref{thm:pigeon} and the converse direction of Dilworth, this is
the static prerequisite for Conjecture~\ref{conj:C1}. The remaining gap is purely
dynamic: one must exhibit a concrete merge schedule along which the per-element static
ceiling becomes a genuine red-degree bound at every step. Lemma~\ref{lem:mono} makes
each part's red interactions a monotone boundary phenomenon, so a bottom-up merge of
chain intervals is expected to keep at most two red boundaries per chain coexisting at
any part.

\section{Algorithms}

\textbf{Algorithm A (Position-type classification).} For element $x$ and sorted chain
$C=(c_1,\dots,c_m)$, return $(\posType_x(c_i))_i$ by testing the four cases of
Definition~\ref{def:postype}; $O(m)$ comparisons.

\textbf{Algorithm B (Transition counting and $2k+1$ verification).} For each chain run
Algorithm A, count consecutive type changes, verify $\le 2$ per chain, sum, add $1$,
and check $\le 2k+1$; $O(|P|)$ per element.

\textbf{Algorithm C (Order-convexity check).} Verify the indices of type $\Incomp$
form a contiguous block (Lemma~\ref{lem:convex}); $O(m)$.

\textbf{Algorithm D (Antichain-width via pigeonhole).} Verify $|A \cap C_j| \le 1$ for
each $j$ and conclude $|A| \le k$ (Theorem~\ref{thm:pigeon}); $O(k|A|)$.

\section{Discussion and future directions}

\begin{conjecture}[Dynamic twin-width bound via chain-interval contraction]\label{conj:C1}
For a finite poset covered by $k$ chains there is a contraction sequence (each
intermediate partition consisting of order-intervals of the chains) along which the red
degree of every part stays $\le 2k+1$; hence twin-width $\le 2k+1$.
\end{conjecture}

\begin{conjecture}[Full Dilworth as hypothesis-discharger]\label{conj:C2}
Every finite poset of width $\le k$ admits a labelling
$\mathrm{chainIdx}: P \to \{1,\dots,k\}$ with comparable label classes (the deep
direction of Dilworth), so the hypotheses of Theorem~\ref{thm:main} follow from
``width $\le k$'' alone.
\end{conjecture}

\begin{conjecture}[Linear lower bound]\label{conj:C3}
There is a family of width-$k$ posets whose strict-order digraph has twin-width
$\ge c\,k$ for an absolute $c > 0$, so the linear dependence on $k$ is unavoidable.
\end{conjecture}

\begin{conjecture}[Undirected analogue]\label{conj:C4}
The undirected incomparability graph of a width-$k$ poset has bounded twin-width (a
function of $k$ only), matching the directed bound up to a constant; this follows the
single-interval structure of Lemma~\ref{lem:convex}.
\end{conjecture}

\section{Conclusion}

We have established the static combinatorial core of a linear relationship between the
width of a finite poset and the twin-width of its strict-order digraph: an outsider's
view of any single chain changes character at most twice, so across $k$ chains at most
$2k$ times, giving a uniform $2k+1$ ceiling on red neighbourhood types per element. The
pigeonhole half of Dilworth ties the chain count to width. The dynamic merge schedule,
the deep direction of Dilworth, a matching lower bound, and the undirected analogue
form a coherent program built on exactly these lemmas.

